/* V10 FinanceStore — authoritative production state; never deletes confirmed real data. */
(() => {
  'use strict';
  const KEY = 'meu_assessor_financeiro_v10_real';
  const LEGACY_KEYS = ['assessor_v180_simulacao_ficticia', 'meu_assessor_financeiro'];
  const SCHEMA = 4;
  const COLLECTIONS = ['accounts', 'cards', 'transactions', 'recurring', 'investments', 'invoices', 'budgets', 'goals'];
  const clone = (value) => JSON.parse(JSON.stringify(value ?? {}));
  const KNOWN_REAL = Object.freeze({ c6OpeningBalance: 34.31, severance: 1069.36, c6Balance: 1103.67, cajuBalance: 881.95, cajuLimit: 1500 });

  function dedupeById(rows) {
    const seen = new Map();
    for (const row of rows || []) {
      if (!row || typeof row !== 'object') continue;
      const id = String(row.id || `${row.date || ''}|${row.value || ''}|${row.desc || row.description || ''}`);
      seen.set(id, { ...(seen.get(id) || {}), ...row, id: row.id || id });
    }
    return [...seen.values()];
  }

  function clean(input) {
    const state = input && typeof input === 'object' ? clone(input) : {};
    COLLECTIONS.forEach((name) => { state[name] = Array.isArray(state[name]) ? state[name] : []; });
    const isDemo = (item) => /(demo|fict[ií]ci|simula[cç][aã]o)/i.test([item.source, item.origin].join(' '));
    state.accounts = dedupeById(state.accounts).filter((item) => !isDemo(item));
    state.cards = dedupeById(state.cards).filter((item) => !isDemo(item));
    state.transactions = dedupeById(state.transactions).filter((item) => !isDemo(item));
    state.recurring = dedupeById(state.recurring).filter((item) => !isDemo(item));
    state.meta = { ...(state.meta || {}), schemaVersion: SCHEMA, environment: 'production', dataMode: 'real', sourceOfTruth: 'FinanceStoreV10' };
    return state;
  }

  function valid(state) {
    return Boolean(state && state.meta?.schemaVersion === SCHEMA && state.meta?.environment === 'production' && state.meta?.dataMode === 'real' && COLLECTIONS.every((name) => Array.isArray(state[name])));
  }

  function migrateSchema(input) {
    const state = clean(input);
    state.meta = { ...state.meta, migratedAt: state.meta?.migratedAt || new Date().toISOString() };
    return state;
  }

  function readStored() {
    for (const key of [KEY, ...LEGACY_KEYS]) {
      try { const value = JSON.parse(localStorage.getItem(key) || 'null'); if (value) return value; } catch (_) {}
    }
    return {};
  }

  function ensureKnownReal(input) {
    const state = clean(input);
    const upsert = (collection, value) => {
      const index = collection.findIndex((item) => item.id === value.id);
      if (index < 0) collection.push(value); else collection[index] = { ...value, ...collection[index] };
    };
    upsert(state.accounts, { id: 'acc_c6', name: 'C6 Bank', type: 'Conta corrente', balance: KNOWN_REAL.c6Balance, openingBalance: KNOWN_REAL.c6OpeningBalance, balanceDate: '2026-09-18', source: 'user-confirmed' });
    upsert(state.cards, { id: 'card_caju_alimentacao', name: 'Caju Alimentação', type: 'Benefício', limit: KNOWN_REAL.cajuLimit, balance: KNOWN_REAL.cajuBalance, availableLimit: KNOWN_REAL.cajuBalance, excludeFromPatrimony: true, source: 'user-confirmed' });
    upsert(state.transactions, { id: 'real_rescisao_20260918', date: '2026-09-18', desc: 'Rescisão Contratual', cat: 'Receitas', sub: 'Rescisão', value: KNOWN_REAL.severance, status: 'posted', source: 'user-confirmed', accountId: 'acc_c6' });
    upsert(state.transactions, { id: 'caju_20260918_bakery_3090', date: '2026-09-18', time: '10:26', desc: 'Bakery and Confectionery Real', cat: 'Alimentação', sub: 'Padaria', value: -30.90, status: 'posted', source: 'Caju', origin: 'Caju Crédito', cardId: 'card_caju_alimentacao', excludeFromPatrimony: true });
    upsert(state.transactions, { id: 'caju_20260918_4905', date: '2026-09-18', time: '12:42', desc: 'Compra Caju', cat: 'Alimentação', value: -49.05, status: 'posted', source: 'Caju', origin: 'Caju Crédito', cardId: 'card_caju_alimentacao', excludeFromPatrimony: true });
    const income = [['2026-10', 6500, 'Salário outubro'], ...['2026-11', '2026-12', '2027-01', '2027-02', '2027-03', '2027-04', '2027-05', '2027-06', '2027-07'].map((month) => [month, 10104.50, 'Salário líquido'])];
    for (const [month, value, desc] of income) upsert(state.transactions, { id: `receita_${String(month).replace('-', '_')}`, date: `${month}-05`, desc, cat: 'Receitas', value, status: 'planned', source: 'user-approved-plan', accountId: 'acc_c6' });
    upsert(state.transactions, { id: 'decimo_terceiro_2026', date: '2026-12-20', desc: '13º salário líquido estimado', cat: 'Receitas', value: 3893.44, status: 'planned', source: 'user-approved-plan', accountId: 'acc_c6' });
    upsert(state.recurring, { id: 'compromissos_base_2026_2027', desc: 'Compromissos mensais', cat: 'Compromissos', value: -3909.90, dueDay: 10, startDate: '2026-10-01', endDate: '2027-07-31', active: true, source: 'user-approved-plan' });
    upsert(state.recurring, { id: 'compromissos_adicionais_ate_maio', desc: 'Compromissos adicionais até maio', cat: 'Compromissos', value: -300, dueDay: 10, startDate: '2026-10-01', endDate: '2027-05-31', active: true, source: 'user-approved-plan' });
    state.meta = { ...state.meta, c6KnownBalance: KNOWN_REAL.c6Balance, c6KnownBalanceAt: '2026-09-18', cajuKnownBalance: KNOWN_REAL.cajuBalance, cajuKnownBalanceAt: '2026-09-18T12:42:00-03:00', realDataProtected: true };
    return state;
  }

  let state = ensureKnownReal(migrateSchema(readStored()));
  const listeners = new Set();
  function persist(reason = 'save') {
    state = ensureKnownReal(clean(state)); localStorage.setItem(KEY, JSON.stringify(state)); window.db = state;
    listeners.forEach((listener) => listener(state, reason));
    document.dispatchEvent(new CustomEvent('finance-store-changed', { detail: { reason } })); return state;
  }
  function get() { return state; }
  function set(next, reason = 'set') { state = ensureKnownReal(next); return persist(reason); }
  function update(mutator, reason = 'update') { const draft = clone(state); mutator(draft); return set(draft, reason); }
  function subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); }
  function upsertTx(transaction) { return update((draft) => { const index = draft.transactions.findIndex((item) => item.id === transaction.id); if (index < 0) draft.transactions.push(transaction); else draft.transactions[index] = { ...draft.transactions[index], ...transaction }; }, 'transaction'); }
  function exportSnapshot() { return clone(state); }
  persist('v10-startup');
  window.FinanceStoreV10 = { KEY, SCHEMA, KNOWN_REAL, get, set, update, subscribe, upsertTx, persist, valid, clean, migrateSchema, ensureKnownReal, exportSnapshot };
})();

/* source: v10/finance-engine.js */
/* V10 FinanceEngine — canonical recurrence, investments and categories */
(()=>{'use strict';const n=v=>Number(v)||0,abs=v=>Math.abs(n(v)),key=v=>String(v||'').slice(0,7),norm=v=>String(v||'Outros').trim()||'Outros';
const planned=s=>/^(planned|planejada|planejado|prevista|previsto)$/i.test(String(s||''));const realized=s=>/^(posted|realized|realizada|realizado|confirmada|confirmado)$/i.test(String(s||''));
function recurringFor(state,k){return(state.recurring||[]).filter(r=>r.active!==false&&(!key(r.startDate)||k>=key(r.startDate))&&(!key(r.endDate)||k<=key(r.endDate)))}
function operational(state,k){return(state.transactions||[]).filter(t=>key(t.date)===k&&!t.transfer&&!t.excludeFromExpense)}
function classify(t){if(t.transfer)return'transfer';if(planned(t.status))return'planned';if(realized(t.status))return'realized';return'other'}
function summary(state,k){const op=operational(state,k);const realizedIncome=op.filter(t=>realized(t.status)&&n(t.value)>0).reduce((a,t)=>a+n(t.value),0),realizedExpense=op.filter(t=>realized(t.status)&&n(t.value)<0).reduce((a,t)=>a+abs(t.value),0),plannedIncome=op.filter(t=>planned(t.status)&&n(t.value)>0).reduce((a,t)=>a+n(t.value),0),direct=op.filter(t=>planned(t.status)&&n(t.value)<0).reduce((a,t)=>a+abs(t.value),0),rec=recurringFor(state,k).reduce((a,r)=>a+abs(r.value),0),investment=investmentPlanFor(state,k).reduce((a,t)=>a+abs(t.value),0);return{k,realizedIncome,realizedExpense,plannedIncome,plannedExpense:direct+rec,recurringExpense:rec,investment}}
function balances(state){const inv=a=>/invest/i.test(String(a.type||''));const usable=(state.accounts||[]).filter(a=>!a.excludeFromPatrimony);const liquid=usable.filter(a=>!inv(a)).reduce((a,x)=>a+n(x.balance),0),invest=usable.filter(inv).reduce((a,x)=>a+n(x.balance),0);return{liquid,invest,patrimony:liquid+invest}}
function patrimony(state){return balances(state).patrimony}
function available(state){return balances(state).liquid}
function investmentPlanFor(state,k){return(state.transactions||[]).filter(t=>key(t.date)===k&&t.transfer&&planned(t.status)&&String(t.destAccountId||t.dest)==='acc_invest_plan')}
function ensureInvestmentPlan(state){state.accounts=state.accounts||[];state.transactions=state.transactions||[];state.investments=state.investments||[];if(!state.accounts.some(a=>a.id==='acc_invest_plan'))state.accounts.push({id:'acc_invest_plan',name:'Investimentos',type:'Investimento',balance:0,openingBalance:0,source:'user-approved'});
 for(let i=0;i<9;i++){const d=new Date(2026,10+i,1),k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),id='aporte_'+k.replace('-','_');state.transactions=state.transactions.filter(t=>!(t.transfer&&key(t.date)===k&&String(t.destAccountId||t.dest)==='acc_invest_plan'&&t.id!==id));let t=state.transactions.find(x=>x.id===id);const v={id,date:k+'-10',desc:'Aporte mensal de investimento',cat:'Investimentos',sub:'Aporte mensal',value:-3000,status:'planned',source:'user-approved-investment-3000',accountId:'acc_c6',destAccountId:'acc_invest_plan',transfer:true,excludeFromExpense:true};t?Object.assign(t,v):state.transactions.push(v)}
 return state}
function categoryTotals(state,k,mode='auto'){const current=new Date().toISOString().slice(0,7),future=mode==='planned'||(mode==='auto'&&k>current),out={};const add=(cat,v)=>out[norm(cat)]=(out[norm(cat)]||0)+abs(v);
 operational(state,k).filter(t=>n(t.value)<0&&(future?planned(t.status):realized(t.status))).forEach(t=>add(t.cat,t.value));if(future)recurringFor(state,k).forEach(r=>add(r.cat,r.value));return Object.entries(out).map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value)}
function chartSeries(state,start='2026-10',count=12){return projection(state,start,count).map(r=>({month:r.k,income:r.plannedIncome,expense:r.plannedExpense,investment:r.investment,liquid:r.liquid,patrimony:r.patrimony,categories:categoryTotals(state,r.k,'planned')}))}
function projection(state,start='2026-10',count=12){let b=balances(state),liq=b.liquid,iv=b.invest,pat=b.patrimony,costs=0;const[y,m]=start.split('-').map(Number),rows=[];for(let i=0;i<count;i++){const d=new Date(y,m-1+i,1),k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),s=summary(state,k);liq+=s.plannedIncome-s.plannedExpense-s.investment;iv+=s.investment;pat+=s.plannedIncome-s.plannedExpense;costs+=s.plannedExpense;rows.push({...s,date:d,label:d.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''),income:s.plannedIncome,expense:s.plannedExpense,investmentMove:s.investment,liquid:liq,invest:iv,patrimony:pat,costs})}return rows}
window.FinanceEngineV10={recurringFor,summary,balances,patrimony,available,projection,investmentPlanFor,ensureInvestmentPlan,categoryTotals,chartSeries,classify};
if(window.FinanceStoreV10){FinanceStoreV10.update(s=>ensureInvestmentPlan(s),'canonical-investment-plan')}
})();

/* source: v10/cloud-sync.js */
/* V10 Cloud adapter — optimistic revisions, explicit conflicts, local real-data protection. */
(() => {
  'use strict';
  const API = 'https://effervescent-marlin-88.convex.site/finance/state';
  const KEY = 'assessor_cloud_sync_key'; const VERSION = 'assessor_v10_cloud_version'; const DEVICE = 'assessor_v10_device';
  const deviceId = localStorage.getItem(DEVICE) || `v10-${crypto.randomUUID()}`; localStorage.setItem(DEVICE, deviceId);
  let busy = false; let lastConflict = null;
  const syncKey = () => localStorage.getItem(KEY) || '';
  async function request(method, body) {
    const response = await fetch(API, { method, headers: { 'Content-Type': 'application/json', 'X-Sync-Key': syncKey() }, body: body ? JSON.stringify(body) : undefined, cache: 'no-store' });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) { const error = new Error(data.error || 'cloud'); error.status = response.status; error.data = data; throw error; }
    return data;
  }
  function mergePreservingReal(local, remote) {
    const next = window.FinanceStoreV10.clean(remote || {}); const protectedLocal = window.FinanceStoreV10.ensureKnownReal(local || {});
    for (const collection of ['accounts', 'cards', 'transactions', 'recurring']) {
      const rows = [...(next[collection] || [])];
      for (const item of protectedLocal[collection] || []) if (/user-confirmed|user-approved|Caju/i.test([item.source, item.origin].join(' ')) && !rows.some((row) => row.id === item.id)) rows.push(item);
      next[collection] = rows;
    }
    return window.FinanceStoreV10.ensureKnownReal(next);
  }
  async function sync(strategy = 'auto') {
    if (busy || !syncKey()) return { ok: false, reason: 'not_ready' }; busy = true;
    try {
      const response = await request('GET'); const remote = response.state; const localVersion = Number(localStorage.getItem(VERSION) || 0); const local = window.FinanceStoreV10.get();
      if (remote && remote.version > localVersion) {
        if (strategy === 'push') { lastConflict = { local, remote, at: new Date().toISOString() }; return { ok: false, conflict: true, preserved: true, remoteVersion: remote.version }; }
        window.FinanceStoreV10.set(mergePreservingReal(local, remote.payload), 'cloud-pull'); localStorage.setItem(VERSION, String(remote.version));
        return { ok: true, direction: 'pull', version: remote.version };
      }
      const baseVersion = Number(remote?.version || 0); const out = await request('POST', { payload: local, baseVersion, deviceId }); localStorage.setItem(VERSION, String(out.version)); lastConflict = null;
      return { ok: true, direction: 'push', version: out.version };
    } catch (error) {
      if (error.status === 409) lastConflict = { local: window.FinanceStoreV10.get(), remoteVersion: error.data?.version, at: new Date().toISOString() };
      return { ok: false, conflict: error.status === 409, preserved: true, error: error.message };
    } finally { busy = false; }
  }
  function configure(value) { if (String(value || '').trim().length < 12) throw new Error('Chave deve ter pelo menos 12 caracteres'); localStorage.setItem(KEY, String(value).trim()); return sync(); }
  function disconnect() { localStorage.removeItem(KEY); localStorage.removeItem(VERSION); lastConflict = null; }
  window.CloudSyncV10 = { sync, configure, disconnect, configured: () => Boolean(syncKey()), mergePreservingReal, status: () => ({ busy, deviceId, version: Number(localStorage.getItem(VERSION) || 0), conflict: lastConflict }) };
})();

/* source: v10/ai-gateway.js */
/* V10 AI gateway — interpretation is server/local; execution is explicit and confirmed. */
(() => {
  'use strict';
  const DEFAULT_ENDPOINT = 'https://effervescent-marlin-88.convex.site/ai/finance';
  const ENDPOINT_KEY = 'assessor_ai_endpoint_v10';
  const endpoint = () => localStorage.getItem(ENDPOINT_KEY) || DEFAULT_ENDPOINT;
  const money = (text) => { const match = String(text).match(/(?:R\$\s*)?([\d.]+(?:,\d{1,2})?)/i); return match ? Number(match[1].replace(/\./g, '').replace(',', '.')) : null; };
  const localContext = () => {
    const state = window.FinanceStoreV10?.get?.(); const month = window.activeMonth || new Date().toISOString().slice(0, 7);
    return { month, summary: window.FinanceEngineV10?.summary?.(state, month), categories: window.FinanceEngineV10?.categoryTotals?.(state, month), dataMode: state?.meta?.dataMode };
  };
  function localInterpret(text) {
    const value = money(text); const income = /recebi|receita|sal[aá]rio|rescis[aã]o|entrou/i.test(text); const expense = /gastei|paguei|comprei|compra|despesa/i.test(text);
    if (value && (income || expense)) return { intent: 'transaction', draft: { date: new Date().toISOString().slice(0, 10), value: income ? Math.abs(value) : -Math.abs(value), cat: income ? 'Receitas' : 'Outros', desc: String(text), status: 'draft' }, mode: 'local' };
    return { intent: 'question', answer: 'Posso analisar seus dados locais ou preparar um lançamento para sua confirmação.', text: String(text), mode: 'local' };
  }
  async function interpret(text) {
    const cleanText = String(text || '').trim(); if (!cleanText) return { intent: 'question', answer: 'Digite uma pergunta ou lançamento.', mode: 'local' };
    try {
      const response = await fetch(endpoint(), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: cleanText, context: localContext() }) });
      if (response.ok) return { ...(await response.json()), mode: 'llm' };
    } catch (_) {}
    return localInterpret(cleanText);
  }
  function validateDraft(draft) { return Boolean(draft && /^\d{4}-\d{2}-\d{2}$/.test(draft.date) && Number.isFinite(Number(draft.value)) && Number(draft.value) !== 0 && String(draft.desc || '').trim()); }
  function validateAction(action) { return action?.type === 'create_transaction' ? validateDraft(action.draft || action) : action?.type === 'answer'; }
  function requiresConfirmation(action) { return ['create_transaction', 'update_transaction', 'delete_transaction', 'cloud_push'].includes(String(action?.type || '')); }
  function execute(draft, confirmed = false) {
    if (!confirmed) return { ok: false, requiresConfirmation: true, draft };
    if (!validateDraft(draft)) return { ok: false, error: 'invalid_draft' };
    const transaction = { ...draft, id: draft.id || `ai_${Date.now()}`, status: 'posted', source: 'ai-confirmed' };
    window.FinanceStoreV10.upsertTx(transaction); return { ok: true, transaction };
  }
  function configure(url) { if (!/^https:\/\//.test(String(url || ''))) throw new Error('HTTPS required'); localStorage.setItem(ENDPOINT_KEY, String(url)); return endpoint(); }
  const hasPublicSecret = () => [...document.scripts].some((script) => /sk-[A-Za-z0-9_-]{16,}/.test(script.textContent || ''));
  window.FinanceAIV10 = { interpret, execute, validateDraft, validateAction, requiresConfirmation, localContext, localInterpret, configure, hasPublicSecret, get endpoint() { return endpoint(); }, publicApiKey: false, backend: true };
})();

/* source: v10/mobile-theme.js */
/* V10 mobile theme controller */
(()=>{'use strict';
 const KEY='assessor_mobile_theme_v10',VALID=new Set(['current','dark','light']);
 function get(){const v=localStorage.getItem(KEY)||'current';return VALID.has(v)?v:'current'}
 function apply(v){v=VALID.has(v)?v:'current';document.documentElement.dataset.mobileTheme=v;localStorage.setItem(KEY,v);document.querySelectorAll('[data-v10-theme]').forEach(b=>b.classList.toggle('active',b.dataset.v10Theme===v));return v}
 function onThemeClick(event){const button=event.target.closest?.('[data-v10-theme]');if(!button)return;event.preventDefault();apply(button.dataset.v10Theme)}
 function mount(){if(document.getElementById('v10ThemeSwitch'))return;const box=document.createElement('div');box.id='v10ThemeSwitch';box.className='v10-theme-switch';box.setAttribute('aria-label','Tema do aplicativo');[['current','Atual'],['dark','Escuro'],['light','Claro']].forEach(([v,l])=>{const b=document.createElement('button');b.type='button';b.dataset.v10Theme=v;b.textContent=l;box.appendChild(b)});box.addEventListener('click',onThemeClick);document.body.appendChild(box);apply(get())}
 apply(get());if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
 window.MobileThemeV10={get,apply,mount};
})();

/* source: v10/mobile-dashboard.js */
/* V10 Mobile Dashboard — navigation only; RuntimeUI remains the sole renderer. */
(() => {
  'use strict';
  function route(name) {
    if (name === 'reports') { window.RuntimeUIV10?.go?.('overview'); requestAnimationFrame(() => document.getElementById('projectionChart')?.scrollIntoView({ behavior: 'smooth', block: 'center' })); return true; }
    return window.RuntimeUIV10?.go?.(name) ?? false;
  }
  function activate(name) { document.querySelectorAll('#v10BottomNav button').forEach((button) => button.classList.toggle('active', button.dataset.mobileRoute === name)); }
  function onNavigate(event) {
    const button = event.target.closest?.('[data-mobile-route]'); if (!button) return;
    event.preventDefault(); const name = button.dataset.mobileRoute;
    if (name === 'add') document.querySelector('.fab-main')?.click();
    else if (name === 'more') document.getElementById('menuBtn')?.click();
    else route(name);
    activate(name);
  }
  function mountNav() {
    if (document.getElementById('v10BottomNav')) return;
    const nav = document.createElement('nav'); nav.id = 'v10BottomNav'; nav.className = 'v10-bottom-nav'; nav.setAttribute('aria-label', 'Navegação principal móvel');
    [['overview', 'Visão Geral', '⌂'], ['transactions', 'Transações', '⇄'], ['add', 'Adicionar', '+'], ['reports', 'Relatórios', '▥'], ['more', 'Mais', '☰']].forEach(([name, label, icon]) => {
      const button = document.createElement('button'); button.type = 'button'; button.dataset.mobileRoute = name; button.setAttribute('aria-label', label); button.innerHTML = `<b>${icon}</b><span>${label}</span>`;
      nav.appendChild(button);
    });
    nav.addEventListener('click', onNavigate); document.body.appendChild(nav); activate('overview');
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mountNav); else mountNav();
  window.MobileDashboardV10 = { mountNav, route, activate };
})();

/* source: v10/render-controller.js */
/* V10 Render Controller — authoritative, one RAF per state/UI change */
(()=>{'use strict';let raf=0,pending=new Set(),running=false,last=0,count=0;
function perform(){raf=0;if(running)return;running=true;const reasons=[...pending];pending.clear();try{
 const ui=window.RuntimeUIV10;if(ui){ui.renderKpis?.();ui.renderCategory?.();ui.renderProjection?.()}
 else {try{window.renderKpis?.()}catch(_){} try{window.renderLists?.()}catch(_){} try{window.renderCommitments?.()}catch(_){} try{window.renderCalendar?.()}catch(_){} try{window.renderInvestment?.()}catch(_){} try{window.renderCharts?.()}catch(_){}}
 last=performance.now();count++;window.dispatchEvent(new CustomEvent('v10-render-complete',{detail:{reasons,count}}));
}finally{running=false;if(pending.size)schedule('queued')}}
function schedule(reason='update'){pending.add(reason);if(running)return;if(!raf)raf=requestAnimationFrame(perform)}
function stats(){return{count,last,pending:[...pending],running}}
window.RenderControllerV10={schedule,perform,stats};
document.addEventListener('finance-store-changed',()=>schedule('store'));
window.addEventListener('resize',()=>schedule('resize'),{passive:true});
})();

/* source: v10/month-sync.js */
/* V10 Item 19 — populated, synchronized month filters. */
(() => {
  'use strict';
  let lock = false;
  const valid = (value) => /^\d{4}-\d{2}$/.test(String(value || ''));
  function monthOptions(start = '2026-09', count = 24) {
    const [year, month] = start.split('-').map(Number); const rows = [];
    for (let index = 0; index < count; index += 1) { const date = new Date(year, month - 1 + index, 1); const value = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`; const label = date.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }); rows.push({ value, label: label.charAt(0).toUpperCase() + label.slice(1) }); }
    return rows;
  }
  function filters() { return [...document.querySelectorAll('.month-filter, #globalMonthFilter, [data-month-scope]')].filter((element, index, all) => element.tagName === 'SELECT' && all.indexOf(element) === index); }
  function ensureOptions(select) {
    const selected = valid(select.value) ? select.value : (valid(window.activeMonth) ? window.activeMonth : '2026-09');
    if (select.options.length < 12) select.innerHTML = monthOptions().map((item) => `<option value="${item.value}">${item.label}</option>`).join('');
    if ([...select.options].some((option) => option.value === selected)) select.value = selected;
    select.disabled = false; select.style.pointerEvents = 'auto';
  }
  function apply(month, source) {
    if (lock || !valid(month)) return false; lock = true;
    try {
      window.activeMonth = month; localStorage.setItem('assessor_active_month', month);
      filters().forEach((select) => { ensureOptions(select); if (select !== source) select.value = month; });
      if (window.monthScopes) Object.keys(window.monthScopes).forEach((key) => { window.monthScopes[key] = month; });
      window.RenderControllerV10?.schedule(`month:${month}`); document.dispatchEvent(new CustomEvent('v10-month-changed', { detail: { month } })); return true;
    } finally { queueMicrotask(() => { lock = false; }); }
  }
  function bind() {
    filters().forEach((select) => { ensureOptions(select); if (select.dataset.v10MonthBound === '1') return; select.dataset.v10MonthBound = '1'; select.addEventListener('change', (event) => apply(event.currentTarget.value, event.currentTarget)); });
    const initial = valid(localStorage.getItem('assessor_active_month')) ? localStorage.getItem('assessor_active_month') : (valid(window.activeMonth) ? window.activeMonth : '2026-09'); apply(initial);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind); else bind();
  document.addEventListener('finance-store-changed', bind);
  window.MonthSyncV10 = { bind, apply, filters, monthOptions, ensureOptions };
})();

/* source: v10/runtime-ui.js */
/* V10 Runtime UI — authoritative navigation, month filters, KPI and chart refresh */
(()=>{'use strict';const valid=k=>/^\d{4}-\d{2}$/.test(String(k||'')),br=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function state(){return FinanceStoreV10?.get?.()} function engine(){return window.FinanceEngineV10}
function go(view){const target=document.getElementById('view-'+view);if(!target)return false;document.querySelectorAll('.module').forEach(x=>x.classList.toggle('active',x===target));document.querySelectorAll('#nav button[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('sidebar')?.classList.remove('open');document.getElementById('overlay')?.classList.remove('show');scrollTo(0,0);window.RenderControllerV10?.schedule('nav:'+view);return true}
function setMonth(k){if(!valid(k))return false;window.activeMonth=k;localStorage.setItem('assessor_active_month',k);if(window.monthScopes)Object.keys(window.monthScopes).forEach(x=>window.monthScopes[x]=k);document.querySelectorAll('select.month-filter').forEach(s=>{if([...s.options].some(o=>o.value===k))s.value=k});window.RenderControllerV10?.schedule('month:'+k);return true}
function renderKpis(){const s=state(),E=engine(),box=document.getElementById('kpis');if(!s||!E||!box)return;const k=window.activeMonth||'2026-09',x=E.summary(s,k),b=E.balances(s),future=k>new Date().toISOString().slice(0,7);const data=[['PATRIMÔNIO TOTAL',b.patrimony,'accounts'],['DISPONÍVEL HOJE',b.liquid,'accounts'],['RECEITAS REALIZADAS',x.realizedIncome,'transactions'],['RECEITAS PREVISTAS',x.plannedIncome,'transactions'],['DESPESAS REALIZADAS',x.realizedExpense,'transactions'],['DESPESAS PREVISTAS',x.plannedExpense,'recurring'],['INVESTIMENTOS',b.invest,'investments']];box.innerHTML=data.map(([l,v,r])=>'<div class="card kpi clickable-card" tabindex="0" data-v10-route="'+r+'"><div class="label">'+l+'</div><div class="value">'+br(v)+'</div><div class="trend neutral">'+k+(future?' · previsto':'')+'</div></div>').join('');box.querySelectorAll('[data-v10-route]').forEach(el=>{el.onclick=()=>go(el.dataset.v10Route);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')go(el.dataset.v10Route)}})}
function renderCategory(){const s=state(),E=engine(),canvas=document.getElementById('categoryChart'),legend=document.getElementById('categoryLegend');if(!s||!E||!canvas)return;const k=window.activeMonth||'2026-09',items=E.categoryTotals(s,k,'auto');if(typeof window.drawDonut==='function')window.drawDonut(canvas,items);if(legend)legend.innerHTML=items.length?items.map(x=>'<div class="legend-line" data-canonical-category="'+x.name+'"><span>'+x.name+'</span><b>'+br(x.value)+'</b></div>').join(''):'<div class="notice">Sem despesas neste mês.</div>'}
function renderProjection(){const s=state(),E=engine();if(!s||!E)return;const n=Number(document.getElementById('periodProjection')?.value||12),rows=E.projection(s,window.activeMonth||'2026-09',n);if(typeof window.drawLineChart==='function'){window.drawLineChart(document.getElementById('projectionChart'),[{name:'Patrimônio projetado',data:rows.map(x=>x.patrimony),color:'#20d8ff'}],rows.map(x=>x.label))}const last=rows.at(-1),b=E.balances(s),h=document.getElementById('projectionHighlights');if(h&&last)h.innerHTML='<div class="projection-highlight"><small>Patrimônio atual</small><b>'+br(b.patrimony)+'</b></div><div class="projection-highlight"><small>Patrimônio projetado</small><b>'+br(last.patrimony)+'</b></div><div class="projection-highlight"><small>Custos no período</small><b>'+br(last.costs)+'</b></div><div class="projection-highlight"><small>Investimentos projetados</small><b>'+br(last.invest)+'</b></div>'}
function bind(){document.addEventListener('click',e=>{const b=e.target.closest('#nav button[data-view],[data-v10-route]');if(b){e.preventDefault();e.stopPropagation();go(b.dataset.view||b.dataset.v10Route)}},true);document.addEventListener('change',e=>{if(e.target.matches('select.month-filter')){e.stopImmediatePropagation();setMonth(e.target.value)}},true);document.getElementById('menuBtn')?.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.toggle('open');document.getElementById('overlay')?.classList.toggle('show')},true);renderKpis();renderCategory();renderProjection()}
window.RuntimeUIV10={go,setMonth,renderKpis,renderCategory,renderProjection};
function takeover(){
 window.renderAll=()=>window.RenderControllerV10?.schedule('legacy-renderAll');
 window.renderKpis=renderKpis;
 window.renderCharts=()=>window.RenderControllerV10?.schedule('legacy-renderCharts');
 bind();window.RenderControllerV10?.schedule('runtime-ready');
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',takeover);else takeover();
document.addEventListener('finance-store-changed',()=>window.RenderControllerV10?.schedule('store-ui'));
})();

/* source: v10/experience.js */
/* V10 Experience — chart, agenda and reconciliation integration over the canonical Store/Engine. */
(() => {
  'use strict';
  const engine = () => window.FinanceEngineV10; const state = () => window.FinanceStoreV10?.get();
  const monthKey = (value) => String(value || '').slice(0, 7); const abs = (value) => Math.abs(Number(value) || 0);
  const currentMonth = () => window.activeMonth || new Date().toISOString().slice(0, 7);
  const brl = (value) => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  function bindCharts() {
    document.querySelectorAll('#categoryLegend .legend-line,[data-canonical-category]').forEach((element) => {
      element.tabIndex = 0; element.setAttribute('role', 'button');
      const open = () => { const name = element.dataset.canonicalCategory || element.querySelector('span')?.textContent?.trim(); if (name && typeof window.openCategoryDetail === 'function') window.openCategoryDetail(name); };
      element.onclick = open; element.onkeydown = (event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); open(); } };
    });
    ['categoryChart', 'projectionChart'].forEach((id) => { const canvas = document.getElementById(id); if (canvas) { canvas.tabIndex = 0; canvas.setAttribute('aria-label', id === 'categoryChart' ? 'Gráfico interativo de despesas por categoria' : 'Gráfico interativo de projeção financeira'); } });
  }
  function agendaEvents(month = currentMonth()) {
    const store = state(); if (!store || !engine()) return [];
    const events = [];
    (store.transactions || []).filter((item) => monthKey(item.date) === month).forEach((item) => events.push({ date: item.date, type: item.transfer ? 'investment' : 'transaction', title: item.desc || item.description || 'Lançamento', value: Number(item.value) || 0, status: item.status, id: item.id }));
    engine().recurringFor(store, month).forEach((item) => events.push({ date: `${month}-${String(item.dueDay || item.due || 10).padStart(2, '0')}`, type: 'recurring', title: item.desc || item.description || 'Compromisso', value: -abs(item.value), status: 'planned', id: item.id }));
    return events.sort((a, b) => a.date.localeCompare(b.date));
  }
  function renderAgenda(month = currentMonth()) {
    const target = document.getElementById('calendarEvents'); if (!target) return [];
    const events = agendaEvents(month); target.innerHTML = events.length ? events.map((item) => `<div class="item" data-v10-agenda-id="${item.id}"><div class="ico">${item.type === 'recurring' ? '↻' : item.type === 'investment' ? '↗' : '•'}</div><div><b>${item.title}</b><small>${item.date.split('-').reverse().join('/')} · ${item.status}</small></div><div class="amount ${item.value < 0 ? 'down' : 'up'}">${brl(item.value)}</div></div>`).join('') : '<div class="notice">Sem eventos financeiros neste mês.</div>';
    return events;
  }
  function reconcile(month = currentMonth()) {
    const store = state(); if (!store) return { month, cases: [], unclassified: 0 };
    const transactions = (store.transactions || []).filter((item) => monthKey(item.date) === month); const cases = []; const seen = new Map();
    transactions.filter((item) => item.classificationPending || item.status === 'provisional').forEach((item) => cases.push({ id: item.id, type: 'classification', status: 'pending', description: item.desc, value: item.value }));
    transactions.forEach((item) => { const signature = [item.date, item.value, item.desc, item.accountId || item.cardId || ''].join('|'); if (seen.has(signature)) cases.push({ id: item.id, type: 'possible-duplicate', status: 'review', matches: seen.get(signature), description: item.desc, value: item.value }); else seen.set(signature, item.id); });
    return { month, cases, unclassified: cases.filter((item) => item.type === 'classification').length };
  }
  function renderReconciliation(month = currentMonth()) {
    const result = reconcile(month); const target = document.getElementById('reconcileStats'); if (!target) return result;
    target.innerHTML = `<div class="row-list"><div class="item"><div class="ico">◎</div><div><b>${result.cases.length} caso(s) para revisar</b><small>${result.unclassified} classificação(ões) pendente(s) · nenhuma alteração automática</small></div></div></div>`; return result;
  }
  function cajuStatus() { const store = state(); if (!store) return null; const card = (store.cards || []).find((item) => item.id === 'card_caju_alimentacao'); const spent = (store.transactions || []).filter((item) => item.cardId === 'card_caju_alimentacao' && Number(item.value) < 0 && /posted|realized|confirm/i.test(String(item.status))).reduce((sum, item) => sum + abs(item.value), 0); return card ? { limit: Number(card.limit) || 0, balance: Number(card.balance) || 0, spent, excludeFromPatrimony: card.excludeFromPatrimony === true } : null; }
  function architecture() { return { store: Boolean(window.FinanceStoreV10), engine: Boolean(window.FinanceEngineV10), mobile: Boolean(window.MobileDashboardV10), desktopUsesSameState: window.db === window.FinanceStoreV10?.get() }; }
  function refresh() { bindCharts(); window.V10AgendaEvents = renderAgenda(currentMonth()); window.V10Reconciliation = renderReconciliation(currentMonth()); window.V10Caju = cajuStatus(); }
  function install() { refresh(); document.addEventListener('v10-render-complete', refresh); document.addEventListener('v10-month-changed', refresh); document.addEventListener('finance-store-changed', () => window.RenderControllerV10?.schedule('experience')); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', install); else install();
  window.ExperienceV10 = { bindCharts, agendaEvents, renderAgenda, reconcile, renderReconciliation, cajuStatus, architecture, refresh };
})();

